const app = document.getElementById("app");
const slideElement = document.getElementById("slide");
const pauseButton = document.getElementById("pauseButton");
const progressTrack = document.getElementById("progressTrack");
const progressFill = document.getElementById("progressFill");
let index = 0;
let paused = false;
let elapsed = 0;
let lastFrame = performance.now();

function showSlide(nextIndex) {
  index = (nextIndex + slides.length) % slides.length;
  elapsed = 0;
  const slide = slides[index];
  ["--bg", "--ink", "--muted", "--accent", "--frame"].forEach((name, i) => app.style.setProperty(name, slide.colors[i]));
  document.getElementById("eyebrow").textContent = `Piece ${index + 1}`;
  document.getElementById("title").textContent = slide.title;
  document.getElementById("byline").textContent = slide.author;
  const image = document.getElementById("slideImage");
  image.src = slide.image;
  image.alt = slide.alt;
  const copy = document.getElementById("copy");
  copy.replaceChildren(...slide.paragraphs.map(paragraph => {
    const p = document.createElement("p");
    p.textContent = paragraph;
    return p;
  }));
  document.getElementById("currentNumber").textContent = String(index + 1).padStart(2, "0");
  slideElement.style.animation = "none";
  void slideElement.offsetWidth;
  slideElement.style.animation = "";
  updateProgress();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function updateProgress() {
  const percent = Math.min(100, Math.round(elapsed / slides[index].duration * 100));
  progressFill.style.width = `${percent}%`;
  progressTrack.setAttribute("aria-valuenow", String(percent));
}

function tick(now) {
  const delta = Math.min(now - lastFrame, 1000);
  lastFrame = now;
  if (!paused && !document.hidden) {
    elapsed += delta;
    if (elapsed >= slides[index].duration) showSlide(index + 1);
    updateProgress();
  }
  requestAnimationFrame(tick);
}

function setPaused(value) {
  paused = value;
  pauseButton.setAttribute("aria-pressed", String(paused));
  pauseButton.setAttribute("aria-label", paused ? "Resume slideshow" : "Pause slideshow");
  pauseButton.querySelector(".pause-icon").textContent = paused ? "▶" : "Ⅱ";
  pauseButton.querySelector(".pause-label").textContent = paused ? "Play" : "Pause";
}

pauseButton.addEventListener("click", () => setPaused(!paused));
document.getElementById("previousButton").addEventListener("click", () => showSlide(index - 1));
document.getElementById("nextButton").addEventListener("click", () => showSlide(index + 1));
document.addEventListener("keydown", event => {
  if (event.key === "ArrowLeft") showSlide(index - 1);
  if (event.key === "ArrowRight") showSlide(index + 1);
  if (event.key === " " && event.target === document.body) {
    event.preventDefault();
    setPaused(!paused);
  }
});
showSlide(0);
requestAnimationFrame(tick);
